


-- --------------------------------------------------------
-- Table structure and data for: fileTbl
-- --------------------------------------------------------



-- --------------------------------------------------------
-- Table structure and data for: logTbl
-- --------------------------------------------------------
DROP TABLE IF EXISTS `logTbl`;
CREATE TABLE `logTbl` (
  `id` int NOT NULL AUTO_INCREMENT,
  `scraper` varchar(255) NOT NULL,
  `file_id` int DEFAULT NULL,
  `user_id` int NOT NULL,
  `start_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `end_time` timestamp NULL DEFAULT NULL,
  `no_of_url_found` int NOT NULL DEFAULT '0',
  `total_success_url` int NOT NULL DEFAULT '0',
  `total_block_url` int NOT NULL DEFAULT '0',
  `data_scraped` int NOT NULL DEFAULT '0',
  `status` varchar(50) NOT NULL DEFAULT 'RUNNING',
  `output_file_path` varchar(500) DEFAULT NULL,
  `error_message` text,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `process_id` int DEFAULT NULL,
  `job_id` varchar(32) DEFAULT NULL,
  `progress_percent` float NOT NULL DEFAULT '0',
  `total_products` int NOT NULL DEFAULT '0',
  `pending_urls` int NOT NULL DEFAULT '0',
  `running_urls` int NOT NULL DEFAULT '0',
  `completed_urls` int NOT NULL DEFAULT '0',
  `blocked_urls` int NOT NULL DEFAULT '0',
  `main_url_done` int NOT NULL DEFAULT '0',
  `product_url_done` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_logtbl_job_id` (`job_id`),
  KEY `idx_log_user_id` (`user_id`),
  KEY `idx_log_file_id` (`file_id`),
  KEY `idx_log_start_time` (`start_time`),
  KEY `idx_log_status` (`status`),
  KEY `idx_log_file_id_id` (`file_id`,`id`),
  KEY `idx_log_status_id` (`status`,`id`),
  KEY `idx_log_user_id_id` (`user_id`,`id`),
  KEY `idx_log_scraper` (`scraper`),
  CONSTRAINT `logTbl_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `userTbl` (`userid`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


SET FOREIGN_KEY_CHECKS = 1;